    clearImage();editorGeneration++;review=null;
    draft={schema:'lifeos.purchase-draft/1',operation,baseVersionId:p.id,reason:'',operationId:uid('op'),purchaseId:id,versionId:uid('purchasev'),sourceId:uid('source'),capturedAt:new Date().toISOString(),date:operation==='refund'?api.today():e.date,store:e.merchant.name,receiptNumber:e.merchant.receiptNumber||'',paymentMode:s.mode,accountId:s.accountId,transactionRootId:s.transactionRootId||'',total:String(e.totalPence/100),basketDiscount:String(e.adjustments.filter(a=>a.kind==='basket-discount').reduce((n,a)=>n+a.amountPence,0)/100),attachmentName:'',documentHash:'',lines:e.lines.map(l=>{const product=catalog.find(p=>p.versionId===l.productVersionId);return {...line(),id:l.id,kind:l.kind,foodId:l.inventory.foodId||'',productChoice:product?'v:'+product.versionId:'new',description:l.description,brand:product?.brand||'',preparation:product?.preparation||'',packGrams:product?.pack?.unit==='mg'?String(product.pack.amount/1000):'',grams:l.inventory.mode==='receive'?String(l.inventory.grams):'',gross:String(l.grossPence/100),discount:String(e.adjustments.filter(a=>a.kind==='item-discount'&&a.eligibleLineIds.includes(l.id)).reduce((n,a)=>n+a.amountPence,0)/100),category:l.category,refundAmount:'0',returnedGrams:'0'};})};
